head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.vScrenID = "ULDSTF05710.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.dts_Recv;
scwin.vBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = "";
scwin.TR_JOB;
scwin.fr_SecuGrpId;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.VListBzTpCd = LIST_BZ_TP_CD_121;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //신주인수권증권 신주상장

scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.fr_SecuGrpId;
    arrPar[1] = scwin.vIsurCd; // 코드값을 포함할 컨트롤
    arrPar[2] = "S";
    //alert('fr_SecuGrpId'+fr_SecuGrpId);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    if (arrPar[0].ISU_CD != "") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_KOR_NM.setValue(arrPar[0].ISU_KOR_NM);
        txb_ISU_KOR_ABBRV.setValue(arrPar[0].ISU_KOR_ABBRV);
        txb_ISU_ENG_NM.setValue(arrPar[0].ISU_ENG_NM);
        txb_ISU_ENG_ABBRV.setValue(arrPar[0].ISU_ENG_ABBRV);
        txb_ISU_SRT_CD.setValue(arrPar[0].ISU_SRT_CD);
        edt_ISU_RND.setValue(arrPar[0].ISU_RND);
        edt_ISU_DD.setValue(arrPar[0].ISU_DD);
        txb_TARSTK_ISU_NM.setValue(arrPar[0].TARSTK_ISU_NM);
        dts_Isu.setCellData(1, "TARSTK_ISU_CD", arrPar[0].TARSTK_ISU_CD);
    }
};
scwin.fn_SetHeader = function() {
    dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SW_LIST_LISTING_INOUT";
    dts_Isu.reset();
    dts_Isu.insertRow();
    //alert(dts_Isu.text+" dts_Isu.text");

};
scwin.fn_initItem = function() {
    $c.stf.setObjectValue(cmb_LIST_METHD_TP_CD, LIST_METHD_TP_CD_1);
};
scwin.fn_recv_read_sync = function(row) {
    dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.dts_Recv.getCellData(row, "BZ_PROCS_NO"));
    dts_Isu.setCellData(1, "ACPT_NO", scwin.dts_Recv.getCellData(row, "ACPT_NO"));
    //dts_Isu.NameString(1, "LIST_METHD_TP_CD") = LIST_METHD_TP_CD_1
    dts_Isu.setCellData(1, "ISU_DD", scwin.dts_Recv.getCellData(row, "ISU_DD"));
    dts_Isu.setCellData(1, "LIST_SHRS", scwin.dts_Recv.getCellData(row, "LIST_SHRS"));
    dts_Isu.setCellData(1, "NPARVALSTK_YN", scwin.dts_Recv.getCellData(row, "NPARVALSTK_YN"));
    dts_Isu.setCellData(1, "EXER_PRC", scwin.dts_Recv.getCellData(row, "EXER_PRC"));
    dts_Isu.setCellData(1, "ISU_SHRS", scwin.dts_Recv.getCellData(row, "ISU_SHRS"));
    dts_Isu.setCellData(1, "TOT_ISU_PRC", scwin.dts_Recv.getCellData(row, "TOT_ISU_PRC"));
    dts_Isu.setCellData(1, "EXER_STRT_DD", scwin.dts_Recv.getCellData(row, "EXER_STRT_DD"));
    dts_Isu.setCellData(1, "EXER_END_DD", scwin.dts_Recv.getCellData(row, "EXER_END_DD"));
    dts_Isu.setCellData(1, "REMK", scwin.dts_Recv.getCellData(row, "REMK"));
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "2") {
        dts_Isu.setCellData(1, "LIST_DD", scwin.dts_Recv.getCellData(row, "LIST_DD"));
    }
    if (dts_Isu.getCellData(1, "NPARVALSTK_YN") == 'Y') {
        chk_NPARVALSTK_YN.setValue(1);
    } else {
        chk_NPARVALSTK_YN.setValue(0);
    }
    scwin.fn_initItem();
};
scwin.fn_read_sync = function() {
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_NEW_ISS_SWR_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
    if (dts_Isu.getCellData(1, "NPARVALSTK_YN") == 'Y') {
        chk_NPARVALSTK_YN.setValue(1);
    }
    dts_Eng_Isu.DataID = encodeURI(url);
    dts_Eng_Isu.reset();
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if (scwin.TR_JOB == 'I') {
        if ($c.pre_newlisting.fn_checkDoubleInput(dts_DoubleChk, $c.stf.getObjectValue(txb_ISU_CD))) return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_SRT_CD) == "") {
        $c.win.alert("[종목단축코드]항목값이  없습니다."); //txb_ISU_SRT_CD.focus();return false;

    }
    if ($c.stf.getObjectValue(txb_ISU_KOR_NM) == "") {
        $c.win.alert("[한글종목명]을 입력하세요.");
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_KOR_ABBRV) == "") {
        $c.win.alert("[한글종목약명]을 입력하세요.");
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_ENG_NM) == "") {
        $c.win.alert("[영문종목명]을 입력하세요.");
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_ENG_ABBRV) == "") {
        $c.win.alert("[영문종목약명]을 입력하세요.");
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_DD) == "") {
        $c.win.alert("[발행일]을 입력하세요.");
        edt_ISU_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
        $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }

    /*if (getObjectValue(edt_EXER_STRT_DD) == "") {
    	alert("[행사시작일]을 입력하세요.");edt_EXER_STRT_DD.focus();return false;
    }*/
    /* 2009.09.24 행사 시작일을 이전도 입력할 수 있게 

    if (vCurDate >= getObjectValue(edt_EXER_STRT_DD)) {
    	alert("[행사시작일]을 현재일이후로 입력하세요.");edt_EXER_STRT_DD.focus();return false;
    }
    */


    if ($c.stf.getObjectValue(edt_EXER_END_DD) == "") {
        $c.win.alert("[행사종료일]을 입력하세요.");
        edt_EXER_END_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_EXER_END_DD)) {
        $c.win.alert("[행사종료일]을 현재일이후로 입력하세요.");
        edt_EXER_END_DD.focus();
        return false;
    }
    if (parseInt(edt_EXER_STRT_DD.getValue(), 10) >= parseInt(edt_EXER_END_DD.getValue(), 10)) {
        $c.win.alert("[행사시작일]은 [행사종료일]보다 작아야 합니다. 다시 입력해주세요");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == "") {
        $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_SHRS) == "") {
        $c.win.alert("[상장증권수량]을 입력하세요.");
        edt_LIST_SHRS.focus();
        return false;
    }
    //if (! fn_checkNumber(edt_LIST_SHRS, '상장증권수량')) return false;

    if ($c.stf.getObjectValue(edt_ISU_SHRS) == "") {
        $c.win.alert("[발행주식수]을 입력하세요.");
        edt_ISU_SHRS.focus();
        return false;
    }
    //if (! fn_checkNumber(edt_ISU_SHRS, '발행주식수')) return false;

    if (dts_Isu.getCellData(1, "NPARVALSTK_YN") != 'Y' && $c.stf.getObjectValue(edt_EXER_PRC) == "") {
        $c.win.alert("[행사가격]을 입력하세요.");
        edt_EXER_PRC.focus();
        return false;
    }
    //if (! fn_checkNumber(edt_EXER_PRC, '행사가격')) return false;

    if ($c.stf.getObjectValue(edt_TOT_ISU_PRC) == "") {
        $c.win.alert("[발행가액총액]을 입력하세요.");
        edt_TOT_ISU_PRC.focus();
        return false;
    }
    //if (! fn_checkNumber(edt_TOT_ISU_PRC, '발행가액총액')) return false;

    if ($c.stf.getObjectValue(txb_ISU_RSN_CONTN) == "") {
        $c.win.alert("[발행사유]를 입력하세요.");
        txb_ISU_RSN_CONTN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_SUBSRGHT_CONTN) == "") {
        $c.win.alert("[신주인수권의 내용]를 입력하세요.");
        txb_SUBSRGHT_CONTN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_SUBSRGHT_EXERTM_PAYMETHD_CONTN) == "") {
        $c.win.alert("[신주의 납입방법]를 입력하세요.");
        txb_SUBSRGHT_EXERTM_PAYMETHD_CONTN.focus();
        return false;
    }

    /* 2009-04-24  신주인수권증권 신주상장 중복입력체크 */
    ///*
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, $c.stf.getObjectValue(txb_ISU_CD), $c.stf.getObjectValue(edt_LIST_DD), scwin.vBzProcsNo, LIST_BZ_TP_CD_121)) {
        return false;
    }
    return true;
};
scwin.fn_checkNumber = function(obj, str) {
    if ($c.stf.getObjectValue(obj) <= 100) {
        $c.win.alert("[" + str + "]를 '" + $c.stf.getObjectValue(obj) + "'으로 입력하셨습니다. 확인 후 재입력바랍니다.");
        obj.focus();
        return false;
    }
    return true;
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vAcptNo == "") {
            scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            //dts_Isu.UserStatus(1) = TB_JOB_INSERT;
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            scwin.fn_trs(TRS_IDX_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TRS_IDX_UPDATE);
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.fn_trs(TRS_IDX_DELETE);
};
scwin.fn_trs = function(trsIdx) {
    if (scwin.TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    //alert("[fn_trs vBzProcsNo] ."+vBzProcsNo);
    //dts_Isu.NameValue(1, "JOB_TYPE") = trsIdx;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    dts_Isu.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_Isu.setCellData(1, "LIST_BZ_TP_CD", scwin.VListBzTpCd); /*ORG SRC: dts_Isu.NameString(1, "NPARVALSTK_YN") = (fn_getCheckboxData(chk_NPARVALSTK_YN) == "Y" ? "Y" : '');*/ X = (scwin.fn_getCheckboxData(chk_NPARVALSTK_YN) == "Y" ? "Y" : '');
    trs_Save.Action = $c.lc.fn_encodeNSession("/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveIsuIssChgList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",ACPT_NO=" + scwin.vAcptNo + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=1" + ",LIST_BZ_TP_CD=" + scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_NEW_ISS_SWR_HIST;
    trs_Save.Post();
};
scwin.fn_RecvtIsuDel = function() {
    if (scwin.vAcptNo == "") {
        $c.win.alert('발행예정내역에서 대상종목을 선택하세요');
        return;
    }
    scwin.fn_delete();
};
scwin.fn_dscl = async function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }

    //if (  dts_Isu.IsUpdated  ) {
    //	alert(getMessageParam("MSG-0022", ""));
    //	return ;
    //}

    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
        // 유가경우
        scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            arr[0] = "68912";
            arr[1] = scwin.vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            //CopyDataSet( dts_Delistdetail , param_dts_isu) ;
            $c.stf.CopyDataSet(dts_Isu, param_dts_mst);
            return arr.length;
        };
    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "2") {
        // 코스닥인경우
        scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
            arr[0] = "70920";
            arr[1] = scwin.vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
            $c.stf.CopyDataSet(dts_Isu, param_dts_mst);
            $c.stf.CopyDataSet(dts_Eng_Isu, param_dts_mst_eng);
            return arr.length;
        };
    }
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 750;
    var hgt = 825;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {
    var OldGet = scwin.fn_GetPar;
    scwin.fn_GetPar = function(arr) {
        arr[0] = scwin.vBzProcsNo;
        return arr.length;
    };
    $c.lc.fn_PopFindDraft();
    scwin.fn_GetPar = OldGet;
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_all_list_sync;
    fr_fn_list_sync();
};
scwin.fn_setBtnRecvIsuDel = function() {
    if (scwin.vOpenTyp == "R" && scwin.vBzProcsNo != "") {
        btn_RecvIsuDel.src = "../img/btn_RcvdocDel.gif";
        btn_RecvIsuDel.setDisabled(false);
    } else {
        btn_RecvIsuDel.src = "../img/btn_RcvdocDel_d.gif";
        btn_RecvIsuDel.setDisabled(true);
    }
};



/* =============================== */
/*       인쇄버튼 추가 2010.01.21        */
/* =============================== */

scwin.fn_report_read_sync = function(vBzProcsNo, reportCd) {
    var url = "/Listing.do?method=searchIssReport" + "&DIV_IDX=" + reportCd + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Report.DataID = encodeURI(url);
    dts_Report.Reset();
};
scwin.fn_print = function() {

    //dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    //껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();
    scwin.fn_report_read_sync(scwin.vBzProcsNo, DIV_IDX_NEW_ISS_SWR_REPORT);

    //PDF 리포트 파일명
    var pdf_rptname = "RLDSTF00029";
    var userParam = [{
        uid: "COM_NM",
        unm: dts_Report.getCellData(1, "COM_NM")
    }, {
        uid: "ISU_INFO",
        unm: dts_Report.getCellData(1, "ISU_CD") + " / " + dts_Report.getCellData(1, "ISU_SRT_CD")
    }, {
        uid: "ISU_KOR_NM",
        unm: dts_Report.getCellData(1, "ISU_KOR_NM")
    }, {
        uid: "ISU_KOR_ABBRV",
        unm: dts_Report.getCellData(1, "ISU_KOR_ABBRV")
    }, {
        uid: "ISU_ENG_NM",
        unm: dts_Report.getCellData(1, "ISU_ENG_NM")
    }, {
        uid: "ISU_ENG_ABBRV",
