scwin.fn_getCheckboxData = function(obj) {
    if (obj.checked) {
        return 'Y';
    } else {
        return 'N';
    }
};
scwin.img_ISU_CD_onclick = function() {
    if (scwin.vIsurCd == "") {
        $c.win.alert("[회사]를 선택하세요.");
        return;
    }
    scwin.fn_GetPar = fn_GetParIsuCd;
    scwin.fn_SetPar = fn_SetParIsuCd;
    $c.lc.fn_PopFindNewIsuOfIsur();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_RecvIsuDel_onclick = function() {
    scwin.fn_RecvtIsuDel();
};
scwin.dts_BZ_CHECK_OnLoadError = function() {
    $c.stf.alert_error(dts_BZ_CHECK);
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    if (scwin.vOpenTyp == "N" || (scwin.vOpenTyp == "R" && scwin.vBzProcsNo == '')) {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_LIST_DD, false);
        $c.stf.setButtonSetWithDate2(dts_Isu.getCellData(1, "DISCLS_YN"));
    }
    scwin.fn_setBtnRecvIsuDel();
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh(); // 목록 다시 조회
    if (scwin.TR_JOB == 'D') {
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_read_sync();
        buttonSet.setUpdateStatus();

        //코스닥일때 보임
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
            $c.stf.showObj(btn_Print, false);
        } else {
            if (scwin.vOpenTyp == "R" && scwin.vBzProcsNo == "") {
                $c.stf.showObj(btn_Print, false);
            } else {
                $c.stf.showObj(btn_Print, true);
            }
        }
    }
};
