scwin.gform_onload = function() {
    //var parentWin = fn_GetProvider();
    var parentWin = $c.frame.path("../");
    //alert('[parentWin]'+parentWin);
    scwin.dts_Recv = parentWin.scwin.dts_Recv;
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vAcptNo = parentWin.scwin.vAcptNo;
    scwin.vIsurCd = $c.stf.getObjectValue(parentWin.txb_ISUR_CD);
    scwin.fr_SecuGrpId = parentWin.pSecuGrpId;
    scwin.vSPOT_ISU_TRD_MKT_TP_CD = parentWin.scwin.vSPOT_ISU_TRD_MKT_TP_CD;
    edt_APPROV_DD.setValue($c.ut.cGetToday("yyyymmdd"));
    scwin.vOpenTyp = parentWin.scwin.vOpenTyp;
    $c.libRoundPanel.PanelToGroupBox(panel_Item);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성s
    //buttonSet.setDrftInfo( btn_Drft, fn_drft );			// 기안

    if (scwin.vOpenTyp == "R") {
        //접수
        scwin.fn_SetHeader();
        scwin.fn_recv_read_sync(scwin.dts_Recv.getFocusedRowIndex());
        buttonSet.setInsertStatus();
    } else if (scwin.vOpenTyp == "H") {
        //이력
        scwin.fn_read_sync();
    } else if (scwin.vOpenTyp == "N") {
        //신규
        scwin.fn_SetHeader();
        scwin.fn_initItem();
        buttonSet.setInsertStatus();
        scwin.fn_setBtnRecvIsuDel();
    }

    //코스닥일때 보임
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
        $c.stf.showObj(btn_Print, false);
        $c.stf.showObj(label_26, false);
        $c.stf.showObj(edt_APPROV_DD, false);
        $c.stf.showObj(img_APPROV_DD, false);
    } else {
        if (scwin.vOpenTyp == "R" && scwin.vBzProcsNo == "") {
            $c.stf.showObj(btn_Print, false);
            $c.stf.showObj(label_26, false);
            $c.stf.showObj(edt_APPROV_DD, false);
            $c.stf.showObj(img_APPROV_DD, false);
        } else {
            $c.stf.showObj(btn_Print, true);
            $c.stf.showObj(label_26, true);
            $c.stf.showObj(edt_APPROV_DD, true);
            $c.stf.showObj(img_APPROV_DD, true);
        }
    }
};
scwin.img_APPROV_DD_onclick = function() {
    popUpCalendar2(edt_APPROV_DD);
};
